cat > /app/design.py <<'EOF'
import subprocess
seqs={}
cur=None
for line in open('/app/sequences.fasta'):
    line=line.rstrip('\r\n')
    if line.startswith('>'):
        cur=line[1:].strip()
        seqs[cur]=''
    elif cur is not None:
        seqs[cur]+=line
a=seqs['input']
p=215
up=a[p-45:p]
down=a[p:p+45]
cache={}
def tm(s):
    if s not in cache:
        r=subprocess.run(['oligotm','-tp','1','-sc','1','-mv','50','-dv','2','-n','0.8','-d','500',s],capture_output=True,text=True)
        cache[s]=float(r.stdout)
    return cache[s]
hits=[]
for L in range(15,46):
    u=up[-L:]
    tu=tm(u)
    if not 58<=tu<=72: continue
    for M in range(15,46):
        d=down[:M]
        td=tm(d)
        if 58<=td<=72 and abs(tu-td)<=5:
            hits.append((L,M,round(tu,2),round(td,2),u,d))
print('count',len(hits))
for x in hits[:10]:
    print(x)
